import React from "react";
import { Link } from "react-router-dom";
import { ArrowRight, Trophy, CheckCircle2, CircleX, BookOpen } from "lucide-react";
import { questions } from "../data/questions";

export default function Results() {
  const score = Number(localStorage.getItem("prepai-last-score") || 0);
  const answers = JSON.parse(localStorage.getItem("prepai-last-answers") || "{}");
  const ids = JSON.parse(localStorage.getItem("prepai-last-question-ids") || "[]");
  const reviewed = ids.map((id) => questions.find((q) => q.id === id)).filter(Boolean);
  const hasResults = localStorage.getItem("prepai-last-score") !== null;
  const correct = reviewed.filter((q) => answers[q.id] === q.answer).length;
  if (!hasResults) return <div className="empty-state panel"><Trophy size={36} /><h2>Your results will appear here</h2><p>Complete a mock interview to see your score and answer-by-answer feedback.</p><Link className="button button-primary" to="/mock-interview">Start mock interview <ArrowRight size={16} /></Link></div>;
  return <div className="page-stack"><section className="page-intro"><div><span className="eyebrow">PERFORMANCE REVIEW</span><h2>Your interview results</h2><p>Every result is a chance to learn something new.</p></div><Link className="button button-primary" to="/mock-interview">Practice again <ArrowRight size={16} /></Link></section><section className="result-summary-grid"><article className="panel result-summary-main"><div className="result-medal"><Trophy size={28} /></div><span className="muted-label">LATEST SCORE</span><div className="summary-score">{score}<span>%</span></div><p>{score >= 80 ? "Great work — your fundamentals are looking strong." : score >= 60 ? "Good progress. Review missed answers to keep improving." : "Keep practicing. Learning from mistakes is how you improve."}</p></article><article className="panel result-small-stat"><span className="stat-icon green"><CheckCircle2 size={20} /></span><span className="stat-label">Correct answers</span><strong>{correct}</strong><span className="stat-note">out of {reviewed.length} questions</span></article><article className="panel result-small-stat"><span className="stat-icon coral"><CircleX size={20} /></span><span className="stat-label">Needs review</span><strong>{reviewed.length - correct}</strong><span className="stat-note">questions to revisit</span></article></section><section className="panel review-panel"><div className="panel-heading"><div><h3>Detailed answer review</h3><p>Review the explanation for every question.</p></div></div>{reviewed.map((q, i) => <article className="review-row" key={q.id}><div className={`review-status ${answers[q.id] === q.answer ? "review-good" : "review-bad"}`}>{answers[q.id] === q.answer ? <CheckCircle2 size={18} /> : <CircleX size={18} />}</div><div className="review-content"><div className="question-tags"><span className={`topic-tag tag-${q.topic.toLowerCase()}`}>{q.topic}</span><span className="level-tag">Question {i + 1}</span></div><strong>{q.question}</strong><p>Your answer: {answers[q.id] === undefined ? "Not answered" : q.options[answers[q.id]]}</p><p className="correct-answer">Correct answer: {q.options[q.answer]}</p><small>{q.explanation}</small></div></article>)}</section><section className="panel encouragement"><BookOpen size={22} /><div><strong>Turn feedback into progress</strong><p>Revisit the topics you found difficult and try another practice round.</p></div><Link to="/questions" className="panel-link">Study questions <ArrowRight size={15} /></Link></section></div>;
}
